-- Kisan Sahyog — 0023 Schemes, content & new features
-- Single migration for: sarkari_yojana alters + MP-scheme seeds + central FAQ/doc
-- backfill; videos table + admin RPCs + seeds; kisan_sawaal alters (crop/symptom/
-- related_video) + Q&A seeds; farm_events table + admin RPCs + seeds;
-- listing_unavailable_dates table + owner-gated RPCs; pest-report count RPC.
-- Admin writes mirror the require_admin (0012) SECURITY DEFINER pattern.

-- ===========================================================================
-- A. sarkari_yojana — individual scheme pages (slug, level, FAQs, docs, source)
-- ===========================================================================
alter table public.sarkari_yojana add column if not exists slug text;
alter table public.sarkari_yojana add column if not exists government_level text not null default 'central';
alter table public.sarkari_yojana add column if not exists faqs jsonb not null default '[]';
alter table public.sarkari_yojana add column if not exists documents_required_hi text;
alter table public.sarkari_yojana add column if not exists documents_required_en text;
alter table public.sarkari_yojana add column if not exists source_url text;
alter table public.sarkari_yojana add column if not exists last_verified_date date;
alter table public.sarkari_yojana add column if not exists updated_at timestamptz not null default now();

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'sarkari_yojana_slug_key') then
    alter table public.sarkari_yojana add constraint sarkari_yojana_slug_key unique (slug);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'sarkari_yojana_gov_level_chk') then
    alter table public.sarkari_yojana add constraint sarkari_yojana_gov_level_chk check (government_level in ('central','state'));
  end if;
end $$;

-- Expand the category check to cover the MP-scheme categories (machinery, irrigation).
alter table public.sarkari_yojana drop constraint if exists sarkari_yojana_category_check;
alter table public.sarkari_yojana add constraint sarkari_yojana_category_check
  check (category in ('income_support','crop_insurance','credit','equipment','solar','storage','women','general','market','machinery','irrigation'));

