update public.sarkari_yojana set slug='e-nam',            government_level='central' where id='00000000-0000-4000-c000-000000000007';
update public.sarkari_yojana set slug='pm-aasha',         government_level='central' where id='00000000-0000-4000-c000-000000000008';

-- keep updated_at fresh on write
create or replace function public.tg_touch_updated_at()
returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
drop trigger if exists sarkari_yojana_touch on public.sarkari_yojana;
create trigger sarkari_yojana_touch before update on public.sarkari_yojana
  for each row execute function public.tg_touch_updated_at();

-- Extended admin upsert (adds slug, government_level, faqs, documents, source_url,
-- last_verified_date). Drop the old signature first, then recreate.
drop function if exists public.admin_upsert_yojana(uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, boolean, boolean, integer);
create or replace function public.admin_upsert_yojana(
  p_actor_id uuid, p_id uuid,
  p_scheme_name_hi text, p_scheme_name_en text, p_ministry_hi text, p_ministry_en text,
  p_category text, p_description_hi text, p_description_en text,
  p_benefit_hi text, p_benefit_en text, p_eligibility_hi text, p_eligibility_en text,
  p_how_to_apply_hi text, p_how_to_apply_en text, p_official_website text, p_helpline text,
  p_deadline_note_hi text, p_deadline_note_en text,
  p_is_active boolean, p_is_featured boolean, p_sort_order integer,
  p_slug text, p_government_level text, p_faqs jsonb,
  p_documents_required_hi text, p_documents_required_en text,
  p_source_url text, p_last_verified_date date
) returns public.sarkari_yojana
language plpgsql security definer set search_path = public, pg_temp as $$
declare v public.sarkari_yojana%rowtype;
begin
  perform public.require_admin(p_actor_id);
  if p_slug in ('central','mp') then raise exception 'slug_reserved'; end if;
  if p_id is null then
    insert into public.sarkari_yojana (
      scheme_name_hi, scheme_name_en, ministry_hi, ministry_en, category,
      description_hi, description_en, benefit_hi, benefit_en, eligibility_hi, eligibility_en,
      how_to_apply_hi, how_to_apply_en, official_website, helpline, deadline_note_hi, deadline_note_en,
      is_active, is_featured, sort_order, slug, government_level, faqs,
      documents_required_hi, documents_required_en, source_url, last_verified_date
    ) values (
      p_scheme_name_hi, p_scheme_name_en, p_ministry_hi, p_ministry_en, p_category,
      p_description_hi, p_description_en, p_benefit_hi, p_benefit_en, p_eligibility_hi, p_eligibility_en,
      p_how_to_apply_hi, p_how_to_apply_en, p_official_website, p_helpline, p_deadline_note_hi, p_deadline_note_en,
      coalesce(p_is_active,true), coalesce(p_is_featured,false), coalesce(p_sort_order,0),
      p_slug, coalesce(p_government_level,'central'), coalesce(p_faqs,'[]'::jsonb),
      p_documents_required_hi, p_documents_required_en, p_source_url, p_last_verified_date
    ) returning * into v;
  else
    update public.sarkari_yojana set
      scheme_name_hi=p_scheme_name_hi, scheme_name_en=p_scheme_name_en, ministry_hi=p_ministry_hi, ministry_en=p_ministry_en,
      category=p_category, description_hi=p_description_hi, description_en=p_description_en,
      benefit_hi=p_benefit_hi, benefit_en=p_benefit_en, eligibility_hi=p_eligibility_hi, eligibility_en=p_eligibility_en,
      how_to_apply_hi=p_how_to_apply_hi, how_to_apply_en=p_how_to_apply_en, official_website=p_official_website,
      helpline=p_helpline, deadline_note_hi=p_deadline_note_hi, deadline_note_en=p_deadline_note_en,
      is_active=coalesce(p_is_active,true), is_featured=coalesce(p_is_featured,false), sort_order=coalesce(p_sort_order,0),
      slug=p_slug, government_level=coalesce(p_government_level,'central'), faqs=coalesce(p_faqs,'[]'::jsonb),
      documents_required_hi=p_documents_required_hi, documents_required_en=p_documents_required_en,
      source_url=p_source_url, last_verified_date=p_last_verified_date
    where id=p_id returning * into v;
  end if;
  return v;
end $$;
grant execute on function public.admin_upsert_yojana(uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, boolean, boolean, integer, text, text, jsonb, text, text, text, date) to anon, authenticated;

-- ===========================================================================
-- B. videos — admin-managed farming video library
-- ===========================================================================
create table if not exists public.videos (
  id uuid primary key default gen_random_uuid(),
  youtube_id text not null,
  title_hi text not null,
  title_en text,
  channel_name text,
  duration text,
  category text check (category in ('pest','sowing','irrigation','drone','scheme','market','general')),
  thumbnail_url text,
  is_featured boolean not null default false,
  is_active boolean not null default true,
  sort_order integer default 0,
  created_at timestamptz default now()
);
alter table public.videos enable row level security;
grant select on public.videos to anon, authenticated;
drop policy if exists videos_public_read on public.videos;
create policy videos_public_read on public.videos for select to anon, authenticated using (is_active = true);

create or replace function public.get_admin_videos(p_actor_id uuid)
returns setof public.videos language plpgsql security definer set search_path = public, pg_temp as $$
begin perform public.require_admin(p_actor_id);
  return query select * from public.videos order by sort_order, created_at desc; end $$;

create or replace function public.admin_upsert_video(
  p_actor_id uuid, p_id uuid, p_youtube_id text, p_title_hi text, p_title_en text,
  p_channel_name text, p_duration text, p_category text, p_thumbnail_url text,
  p_is_featured boolean, p_is_active boolean, p_sort_order integer
) returns public.videos language plpgsql security definer set search_path = public, pg_temp as $$
declare v public.videos%rowtype;
begin perform public.require_admin(p_actor_id);
  if p_id is null then
    insert into public.videos (youtube_id,title_hi,title_en,channel_name,duration,category,thumbnail_url,is_featured,is_active,sort_order)
    values (p_youtube_id,p_title_hi,p_title_en,p_channel_name,p_duration,p_category,p_thumbnail_url,coalesce(p_is_featured,false),coalesce(p_is_active,true),coalesce(p_sort_order,0))
    returning * into v;
  else
    update public.videos set youtube_id=p_youtube_id,title_hi=p_title_hi,title_en=p_title_en,channel_name=p_channel_name,
      duration=p_duration,category=p_category,thumbnail_url=p_thumbnail_url,is_featured=coalesce(p_is_featured,false),
      is_active=coalesce(p_is_active,true),sort_order=coalesce(p_sort_order,0) where id=p_id returning * into v;
  end if;
  return v; end $$;

create or replace function public.admin_set_video_active(p_actor_id uuid, p_id uuid, p_active boolean)
returns public.videos language plpgsql security definer set search_path = public, pg_temp as $$
declare v public.videos%rowtype;
begin perform public.require_admin(p_actor_id);
  update public.videos set is_active=p_active where id=p_id returning * into v; return v; end $$;

create or replace function public.admin_delete_video(p_actor_id uuid, p_id uuid)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin perform public.require_admin(p_actor_id); delete from public.videos where id=p_id; end $$;

grant execute on function public.get_admin_videos(uuid) to anon, authenticated;
grant execute on function public.admin_upsert_video(uuid,uuid,text,text,text,text,text,text,text,boolean,boolean,integer) to anon, authenticated;
grant execute on function public.admin_set_video_active(uuid,uuid,boolean) to anon, authenticated;
grant execute on function public.admin_delete_video(uuid,uuid) to anon, authenticated;

-- ===========================================================================
-- C. kisan_sawaal — crop/symptom tags (pest banner) + related video cross-link
-- ===========================================================================
alter table public.kisan_sawaal add column if not exists crop text;
alter table public.kisan_sawaal add column if not exists symptom_tag text;
alter table public.kisan_sawaal add column if not exists related_video_id uuid references public.videos(id) on delete set null;

-- Pest/disease "recently reported" aggregation (published rows, last p_days days,
-- crop+symptom set, groups with count >= p_min). Public/anon.
create or replace function public.recent_crop_reports(p_days int default 14, p_min int default 2)
returns table (crop text, symptom_tag text, report_count bigint)
language sql stable security definer set search_path = public, pg_temp as $$
  select crop, symptom_tag, count(*) as report_count
  from public.kisan_sawaal
  where is_published = true and crop is not null and symptom_tag is not null
    and created_at >= now() - make_interval(days => greatest(1, p_days))
  group by crop, symptom_tag
  having count(*) >= greatest(1, p_min)
  order by report_count desc, crop;
$$;
grant execute on function public.recent_crop_reports(int, int) to anon, authenticated;

-- ===========================================================================
-- D. farm_events — KVK / agriculture events
-- ===========================================================================
create table if not exists public.farm_events (
  id uuid primary key default gen_random_uuid(),
  title_hi text not null,
  title_en text,
  description_hi text,
  location text,
  event_date date not null,
  organizer text,
  contact text,
  is_active boolean not null default true,
  created_at timestamptz default now()
);
alter table public.farm_events enable row level security;
grant select on public.farm_events to anon, authenticated;
drop policy if exists farm_events_public_read on public.farm_events;
create policy farm_events_public_read on public.farm_events for select to anon, authenticated
  using (is_active = true and event_date >= current_date);

create or replace function public.get_admin_events(p_actor_id uuid)
returns setof public.farm_events language plpgsql security definer set search_path = public, pg_temp as $$
begin perform public.require_admin(p_actor_id);
  return query select * from public.farm_events order by event_date; end $$;

create or replace function public.admin_upsert_event(
  p_actor_id uuid, p_id uuid, p_title_hi text, p_title_en text, p_description_hi text,
  p_location text, p_event_date date, p_organizer text, p_contact text, p_is_active boolean
) returns public.farm_events language plpgsql security definer set search_path = public, pg_temp as $$
declare v public.farm_events%rowtype;
begin perform public.require_admin(p_actor_id);
  if p_id is null then
    insert into public.farm_events (title_hi,title_en,description_hi,location,event_date,organizer,contact,is_active)
    values (p_title_hi,p_title_en,p_description_hi,p_location,p_event_date,p_organizer,p_contact,coalesce(p_is_active,true))
    returning * into v;
  else
    update public.farm_events set title_hi=p_title_hi,title_en=p_title_en,description_hi=p_description_hi,location=p_location,
      event_date=p_event_date,organizer=p_organizer,contact=p_contact,is_active=coalesce(p_is_active,true) where id=p_id returning * into v;
  end if;
  return v; end $$;

create or replace function public.admin_delete_event(p_actor_id uuid, p_id uuid)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin perform public.require_admin(p_actor_id); delete from public.farm_events where id=p_id; end $$;

grant execute on function public.get_admin_events(uuid) to anon, authenticated;
grant execute on function public.admin_upsert_event(uuid,uuid,text,text,text,text,date,text,text,boolean) to anon, authenticated;
grant execute on function public.admin_delete_event(uuid,uuid) to anon, authenticated;

-- ===========================================================================
-- E. listing_unavailable_dates — equipment availability calendar (owner-managed)
-- ===========================================================================
create table if not exists public.listing_unavailable_dates (
  listing_id uuid not null references public.listings(id) on delete cascade,
  unavailable_date date not null,
  primary key (listing_id, unavailable_date)
);
alter table public.listing_unavailable_dates enable row level security;
grant select on public.listing_unavailable_dates to anon, authenticated;
drop policy if exists lud_public_read on public.listing_unavailable_dates;
create policy lud_public_read on public.listing_unavailable_dates for select to anon, authenticated using (true);

-- Owner-gated toggle (custom auth → verify listing.user_id == actor via SECURITY DEFINER).
create or replace function public.set_listing_unavailable(p_actor_id uuid, p_listing_id uuid, p_date date, p_busy boolean)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not exists (select 1 from public.listings where id = p_listing_id and user_id = p_actor_id) then
    raise exception 'not_listing_owner';
  end if;
  if p_busy then
    insert into public.listing_unavailable_dates (listing_id, unavailable_date)
    values (p_listing_id, p_date) on conflict do nothing;
  else
    delete from public.listing_unavailable_dates where listing_id = p_listing_id and unavailable_date = p_date;
  end if;
end $$;
grant execute on function public.set_listing_unavailable(uuid, uuid, date, boolean) to anon, authenticated;

