-- F2. kisan_sawaal seed (16 published Q&A; crop/symptom_tag for pest banner)
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000001','मेरे खेत की मिट्टी काली और चिकनी है, सोयाबीन बोने से पहले मिट्टी की जाँच कब और कैसे कराऊँ?','सागर की काली भारी मिट्टी में हर 2-3 साल में मिट्टी परीक्षण जरूर कराएँ। खरीफ बुवाई से पहले, यानी अप्रैल-मई में नमूना लें। खेत के अलग-अलग हिस्सों से 15 सेमी गहराई तक 8-10 जगह से मिट्टी लेकर मिलाएँ, फिर आधा किलो नमूना साफ थैली में भरें। नमूने में खाद, मेड़ या पेड़ के पास की मिट्टी न मिलाएँ। इसे KVK सागर या नजदीकी मृदा परीक्षण प्रयोगशाला में जमा करें। रिपोर्ट में pH, नाइट्रोजन, फॉस्फोरस, पोटाश और सल्फर के आधार पर ही खाद तय करें। सटीक सिफारिश के लिए KVK सागर से संपर्क करें।','land','Rehli','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000002','सोयाबीन की बुवाई के लिए सीड ड्रिल सही है या हाथ से छिटककर बोना ठीक रहेगा?','सोयाबीन में सीड ड्रिल (या सीड-कम-फर्टिलाइजर ड्रिल) से बुवाई हाथ से छिटकने की तुलना में बेहतर है। ड्रिल से कतार-से-कतार 30-45 सेमी और गहराई 3-4 सेमी एक समान रहती है, बीज कम लगता है और अंकुरण अच्छा होता है। रिज-फरो या ब्रॉड बेड फरो (BBF) पद्धति सागर की काली मिट्टी में जल-निकास और नमी दोनों के लिए बहुत लाभदायक है, इससे अधिक वर्षा में जड़ें नहीं सड़तीं। छिटकवाँ बुवाई में बीज असमान गहराई पर जाता है और अंकुरण कमजोर होता है। किराए पर ड्रिल कस्टम हायरिंग केंद्र से मिल सकती है। मशीन चयन हेतु KVK सागर से सलाह लें।','equipment','Khurai','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000003','गेहूं की कौन सी किस्म सागर के लिए अच्छी है और सिंचाई कितनी बार करनी चाहिए?','सागर की सिंचित दशा के लिए GW-322, GW-366, HI-1544 और पूसा तेजस (HI-8759, ड्यूरम) जैसी किस्में अच्छी मानी जाती हैं। समय पर बुवाई नवंबर के पहले पखवाड़े में करें। सिंचित गेहूं में सामान्यतः 5-6 सिंचाई की जरूरत होती है और ये क्रांतिक अवस्थाओं पर देना जरूरी है: पहली सिंचाई बुवाई के 20-25 दिन बाद (जड़ जमाव), फिर कल्ले फूटते समय, गाँठ बनते समय, फूल आते समय, दाना भरते समय और दूधिया अवस्था पर। पानी सीमित हो तो पहली और फूल-अवस्था की सिंचाई प्राथमिकता दें। किस्म और बीज दर की पुष्टि KVK सागर से करें।','crop','Bina','Team Kisan Sahyog',true,false,'wheat',null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000004','मेरी सोयाबीन के पत्ते ऊपर से पीले पड़ रहे हैं और पौधे कमजोर दिख रहे हैं, क्या करूँ?','सोयाबीन में पत्तों का पीला पड़ना कई कारणों से होता है। नई पत्तियाँ पीली हों तो अक्सर आयरन की कमी या अधिक पानी से जड़ों तक हवा न पहुँचना कारण होता है; खेत में पानी रुकता हो तो जल-निकास सुधारें। पीली मोजेक वायरस में पत्तों पर पीले-हरे धब्बे और पौधा बौना रहता है, यह सफेद मक्खी से फैलता है। साथ ही सल्फर या नाइट्रोजन की कमी से भी पीलापन आता है। पहले खेत का पानी निकालें, प्रभावित पौधे देखें। सही कारण और दवा-मात्रा जानने के लिए पत्ती का नमूना लेकर तुरंत KVK सागर से संपर्क करें, अंधाधुंध छिड़काव न करें।','pest','Rahatgarh','Team Kisan Sahyog',true,false,'soybean','yellow_leaves') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000005','पड़ोस के खेतों में भी सोयाबीन पीली पड़ रही है, यह पीला मोजेक तो नहीं? कैसे रोकूँ?','अगर पत्तों पर पीले और हरे चकत्ते बन रहे हैं, पौधे बौने रह गए हैं और पास-पास कई खेतों में फैल रहा है, तो यह पीला मोजेक वायरस (YMV) हो सकता है, जो सफेद मक्खी से फैलता है। सबसे पहले रोगग्रस्त पौधों को उखाड़कर खेत से बाहर नष्ट करें ताकि संक्रमण न फैले। सफेद मक्खी नियंत्रण के लिए पीले चिपचिपे ट्रैप लगाएँ और सिफारिश अनुसार कीटनाशक का छिड़काव करें। आगे रोग-सहनशील किस्में ही बोएँ। चूँकि यह क्षेत्र में तेजी से फैल रहा है, सही कीटनाशक और मात्रा के लिए तुरंत KVK सागर या कृषि विभाग से संपर्क करें।','pest','Garhakota','Team Kisan Sahyog',true,false,'soybean','yellow_leaves') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000006','गेहूं की पत्तियों पर भूरे-पीले चकत्ते और नारंगी धारियाँ दिख रही हैं, यह कौन सा रोग है?','गेहूं में पत्तियों पर नारंगी-भूरे धब्बे या धारियाँ दिखें तो यह रतुआ (रस्ट) रोग हो सकता है, जो ठंडी-नम और ओसदार सुबह में तेजी से फैलता है। छूने पर हाथ में पीला-भूरा पाउडर लगे तो यह रस्ट की पुष्टि करता है। यह हवा से पास के खेतों में फैलता है, इसलिए शुरुआत में ही रोकना जरूरी है। खेत में जल-जमाव न होने दें और नाइट्रोजन की अधिकता से बचें। रोग-रोधी किस्में लाभदायक रहती हैं। फफूँदनाशक (जैसे प्रोपिकोनाजोल समूह) का उपयोग सिफारिश अनुसार करें। सही फफूँदनाशक और मात्रा के लिए KVK सागर से तुरंत सलाह लें, ताकि फसल बचाई जा सके।','pest','Malthon','Team Kisan Sahyog',true,false,'wheat','fungal_spots') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000007','चने की फसल में इल्ली (फली छेदक) लग गई है, फलियाँ खा रही है, कैसे नियंत्रण करूँ?','चने में फली छेदक (हेलिकोवर्पा) सबसे बड़ा दुश्मन है, जो फूल और फलियों में छेद कर दाना खा जाती है। सबसे पहले खेत में T आकार की पक्षी-बैठकें (बर्ड पर्च) प्रति एकड़ 8-10 लगाएँ ताकि पक्षी इल्ली खाएँ, और फेरोमोन ट्रैप 4-5 प्रति एकड़ लगाकर निगरानी करें। शुरुआती अवस्था में NPV या नीम आधारित कीटनाशक कारगर रहते हैं। इल्ली बड़ी हो जाए और आर्थिक हानि स्तर पार हो तो सिफारिश अनुसार रासायनिक कीटनाशक छिड़कें। शाम के समय छिड़काव अधिक असरदार होता है। सही दवा और मात्रा की पुष्टि के लिए KVK सागर से संपर्क करें।','pest','Banda','Team Kisan Sahyog',true,false,'gram','pest_visible') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000008','अगले तीन-चार दिन बारिश की संभावना है, मेरी कटी हुई सोयाबीन खेत में पड़ी है, क्या करूँ?','अगर मौसम विभाग ने भारी बारिश का अनुमान दिया है और कटी सोयाबीन खेत में पड़ी है, तो उसे तुरंत सुरक्षित स्थान या तिरपाल से ढके गोदाम में हटाएँ, नहीं तो दाना काला पड़ सकता है और अंकुरित होकर गुणवत्ता गिर जाएगी। खड़ी फसल पक चुकी हो तो बारिश से पहले कटाई कर लें; न पकी हो तो खेत का जल-निकास खुला रखें ताकि पानी न रुके। मड़ाई तभी करें जब दाना अच्छी तरह सूखा हो (नमी लगभग 12-13%)। मौसम की ताजा जानकारी के लिए IMD/मौसम ऐप और स्थानीय कृषि विभाग की सलाह देखते रहें, तथा KVK सागर से भंडारण संबंधी मार्गदर्शन लें।','weather','Deori','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000009','इस साल सोयाबीन का भाव कैसा रहेगा और मंडी में बेचने का सही समय क्या है?','भाव का सटीक अनुमान लगाना कठिन है, पर कुछ बातें ध्यान रखें। नई फसल आने पर (अक्टूबर-नवंबर) आवक ज्यादा होने से भाव अक्सर दबाव में रहते हैं; थोड़ा रुककर बेचने पर बेहतर दाम मिल सकते हैं, बशर्ते भंडारण सूखा और सुरक्षित हो। बेचने से पहले सागर, खुरई या नजदीकी मंडी के दैनिक भाव eNAM पोर्टल या मंडी बोर्ड से जरूर देखें और कई मंडियों की तुलना करें। सरकारी खरीद (MSP) की तिथियों और पंजीयन की जानकारी रखें। एक साथ पूरी उपज न बेचकर किश्तों में बेचना जोखिम घटाता है। बाजार रुझान और भंडारण सलाह के लिए KVK सागर या कृषि विभाग से संपर्क करें।','market','Sagar','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000010','प्रधानमंत्री किसान सम्मान निधि (PM-KISAN) की किस्त नहीं आ रही, क्या करूँ?','PM-KISAN की किस्त रुकने का सबसे आम कारण e-KYC न होना, बैंक खाते का आधार से लिंक न होना, या भूलेख सत्यापन अधूरा रहना है। सबसे पहले pmkisan.gov.in पर ''Beneficiary Status'' में अपना आधार/मोबाइल नंबर डालकर स्थिति देखें, वहीं गलती का कारण दिखेगा। e-KYC पोर्टल पर OTP से या नजदीकी CSC केंद्र पर करा सकते हैं। बैंक खाता आधार से DBT हेतु लिंक कराएँ। भूलेख सुधार के लिए पटवारी या तहसील से संपर्क करें। समस्या बनी रहे तो PM-KISAN हेल्पलाइन 155261 या 1800-115-526 पर बात करें, या नजदीकी कृषि कार्यालय/CSC से सहायता लें।','scheme','Shahgarh','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000011','ड्रोन दीदी योजना क्या है और गाँव में ड्रोन से दवा छिड़काव कैसे करा सकते हैं?','नमो ड्रोन दीदी योजना के तहत महिला स्वयं सहायता समूहों (SHG) को ड्रोन दिए जाते हैं ताकि वे किसानों को किराए पर दवा और तरल उर्वरक के छिड़काव की सेवा दे सकें। इससे कम समय में बड़े रकबे पर एक समान छिड़काव होता है, पानी और दवा की बचत होती है और किसान रसायन के सीधे संपर्क से बचते हैं। सेवा लेने के लिए अपने क्षेत्र के SHG, कृषि सखी, या कृषि विभाग/आत्मा कार्यालय से संपर्क करें और छिड़काव की तिथि व दर पहले तय कर लें। सोयाबीन-गेहूं जैसी फसलों में यह उपयोगी है। नजदीकी उपलब्धता और पंजीयन जानने के लिए KVK सागर या कृषि विभाग से संपर्क करें।','drone_didi','Khurai','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000012','मसूर की बुवाई का सही समय, बीज दर और बीज उपचार क्या होना चाहिए?','मसूर रबी की फसल है, सागर में इसकी बुवाई अक्टूबर के दूसरे पखवाड़े से नवंबर के पहले पखवाड़े तक सबसे अच्छी रहती है। सामान्यतः बीज दर लगभग 30-40 किलो प्रति हेक्टेयर (बड़े दाने वाली किस्मों में अधिक) रखी जाती है, कतार से कतार दूरी करीब 30 सेमी। बुवाई से पहले बीज को फफूँदनाशक (जैसे थायरम/कार्बेन्डाजिम) से उपचारित करें, फिर राइजोबियम और PSB कल्चर से टीका लगाएँ, इससे जड़-गाँठें बनती हैं और नाइट्रोजन स्थिरीकरण होता है। कल्चर लगाने के बाद बीज छाया में सुखाकर तुरंत बोएँ। किस्म चयन और सटीक बीज दर की पुष्टि KVK सागर से करें।','crop','Rehli','Team Kisan Sahyog',true,false,'lentil',null) on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000013','सरसों की फसल में माहू (चेंपा) लग गया है, टहनियों पर छोटे कीड़ों का झुंड है, क्या करूँ?','सरसों में माहू (एफिड) फूल और फलियों बनने के समय टहनियों व फलियों पर झुंड में चिपककर रस चूसता है, जिससे पौधा कमजोर और चिपचिपा हो जाता है और उपज घटती है। ठंडे-नम मौसम में यह तेजी से बढ़ता है। शुरुआत में पीले चिपचिपे ट्रैप लगाएँ और अधिक प्रभावित टहनियाँ तोड़कर नष्ट करें। इसका प्राकृतिक शत्रु लेडीबर्ड बीटल भी मददगार है, इसलिए बिना जरूरत छिड़काव न करें। संख्या अधिक हो तो सिफारिश अनुसार कीटनाशक शाम के समय छिड़कें, ताकि परागण करने वाली मधुमक्खियों को नुकसान न हो। सही दवा और मात्रा के लिए KVK सागर से संपर्क करें।','pest','Bina','Team Kisan Sahyog',true,false,'mustard','pest_visible') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000014','धान की नर्सरी में पौधे पीले और कमजोर रह गए हैं, रोपाई से पहले क्या करूँ?','धान की नर्सरी में पौधों का पीला रहना अक्सर नाइट्रोजन या जिंक की कमी, अधिक पानी भरे रहने, या कम रोशनी से होता है। पहले नर्सरी में पानी का स्तर ठीक करें, लगातार गहरा पानी न भरें। जिंक की कमी में बीच की पत्तियाँ पीली-भूरी होती हैं, ऐसे में जिंक सल्फेट का प्रयोग लाभकारी रहता है। रोपाई तब करें जब पौधे 21-25 दिन के, 4-5 पत्ती वाले और स्वस्थ हों। कमजोर पौधों की रोपाई न करें। संतुलित खाद रिपोर्ट अनुसार दें। सही कारण जानने के लिए नर्सरी की मिट्टी और पौधे दिखाकर KVK सागर से सलाह लें, फिर ही खाद या दवा का उपयोग करें।','pest','Garhakota','Team Kisan Sahyog',true,false,'paddy','yellow_leaves') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000015','मक्का की फसल में तना छेदक जैसा कीट पत्तियों में छेद कर रहा है और गोभ खराब हो रही है, उपाय बताएँ?','मक्का में पत्तियों पर कतार में छेद, गोभ (पौधे का बीच वाला भाग) में लीद जैसा मल और मुरझाना दिखे तो यह फॉल आर्मीवर्म या तना छेदक हो सकता है, जो सागर क्षेत्र में मक्का का प्रमुख कीट है। पहले खेत की नियमित निगरानी करें और गोभ में दिख रही इल्लियों को हाथ से निकालकर नष्ट करें। शुरुआती अवस्था में गोभ में सूखी रेत या नीम आधारित कीटनाशक डालना कारगर रहता है, तथा फेरोमोन ट्रैप से नर पतंगे पकड़ें। अधिक प्रकोप पर सिफारिश अनुसार रासायनिक कीटनाशक गोभ को लक्ष्य कर डालें। सही दवा और मात्रा के लिए तुरंत KVK सागर से संपर्क करें।','pest','Deori','Team Kisan Sahyog',true,false,'maize','pest_visible') on conflict (id) do nothing;
insert into public.kisan_sawaal (id,question_hi,answer_hi,category,asked_by_village,answered_by,is_published,is_featured,crop,symptom_tag) values ('00000000-0000-4000-e000-000000000016','खेती से जुड़ी सरकारी सलाह और मौसम की जानकारी मुझे नियमित रूप से कहाँ से मिल सकती है?','किसानों के लिए कई भरोसेमंद स्रोत हैं। कृषि विज्ञान केंद्र (KVK) सागर समय-समय पर फसल सलाह, प्रशिक्षण और मिट्टी परीक्षण की सुविधा देता है, वहाँ संपर्क में रहें। मौसम की सटीक जानकारी के लिए भारतीय मौसम विभाग (IMD) और ''मेघदूत'' ऐप उपयोगी हैं। बाजार भाव के लिए eNAM पोर्टल और मंडी बोर्ड देखें। योजनाओं की जानकारी कृषि विभाग/आत्मा कार्यालय और CSC केंद्र से मिलती है। किसान कॉल सेंटर 1800-180-1551 पर निःशुल्क कृषि सलाह ले सकते हैं। इसके अलावा गाँव के कृषि सखी और पटवारी भी मार्गदर्शन देते हैं। किसी भी संदेह में सबसे पहले KVK सागर से संपर्क करना सुरक्षित रहता है।','general','Sagar','Team Kisan Sahyog',true,false,null,null) on conflict (id) do nothing;

