-- F5. MP state schemes seed (verified, government_level=state)
insert into public.sarkari_yojana (id,scheme_name_hi,scheme_name_en,ministry_hi,ministry_en,category,description_hi,description_en,benefit_hi,benefit_en,eligibility_hi,eligibility_en,how_to_apply_hi,how_to_apply_en,official_website,helpline,is_active,is_featured,sort_order,slug,government_level,faqs,documents_required_hi,documents_required_en,source_url,last_verified_date) values ('00000000-0000-4000-c000-000000000009','मुख्यमंत्री किसान कल्याण योजना','Mukhyamantri Kisan Kalyan Yojana (CM Farmer Welfare Scheme)','मध्यप्रदेश शासन, किसान कल्याण तथा कृषि विकास विभाग','Govt of Madhya Pradesh, Department of Farmer Welfare & Agriculture Development','income_support','मुख्यमंत्री किसान कल्याण योजना मध्यप्रदेश सरकार की आय-सहायता योजना है, जो पीएम-किसान सम्मान निधि के अतिरिक्त पात्र किसानों को हर वर्ष 6,000 रुपये देती है। यह राशि 2,000 रुपये की तीन किस्तों में सीधे आधार-लिंक बैंक खाते (डीबीटी) में भेजी जाती है। पीएम-किसान के 6,000 रुपये मिलाकर किसान को कुल 12,000 रुपये सालाना मिलते हैं। योजना का लाभ लेने के लिए पीएम-किसान में पंजीकरण अनिवार्य है।','Mukhyamantri Kisan Kalyan Yojana is a Madhya Pradesh state income-support scheme that pays eligible farmers an extra Rs 6,000 per year over and above PM-Kisan Samman Nidhi, in three DBT installments of Rs 2,000. Combined with PM-Kisan a farmer receives a total of Rs 12,000 annually. PM-Kisan registration is mandatory.','पात्र किसान को राज्य सरकार की ओर से हर साल 6,000 रुपये अतिरिक्त मिलते हैं। यह राशि 2,000-2,000 रुपये की तीन समान किस्तों में डीबीटी के माध्यम से सीधे बैंक खाते में जमा होती है। पीएम-किसान की राशि मिलाकर किसान को कुल 12,000 रुपये प्रति वर्ष प्राप्त होते हैं।','Eligible farmers receive an additional Rs 6,000 per year from the state government, credited via DBT in three equal installments of Rs 2,000. Combined with PM-Kisan the farmer gets Rs 12,000 per year.','किसान मध्यप्रदेश का स्थायी निवासी हो; पीएम-किसान सम्मान निधि योजना में पहले से पंजीकृत हो; खेती योग्य कृषि भूमि का स्वामी हो; भूमि अभिलेख राजस्व विभाग से सत्यापित हों; आधार से जुड़ा सक्रिय बैंक खाता हो; तथा फार्मर रजिस्ट्री आईडी हो।','Permanent resident of MP; already registered under PM-Kisan; owns cultivable land; land records verified by Revenue Dept; active Aadhaar-linked bank account; has a Farmer Registry ID.','1. सुनिश्चित करें कि आप पीएम-किसान योजना में पंजीकृत हैं।
2. अपने क्षेत्र के पटवारी या स्थानीय कृषि/राजस्व कार्यालय से संपर्क कर आवेदन/सत्यापन कराएं।
3. आधार, बैंक पासबुक और भूमि अभिलेख उपलब्ध कराएं।
4. भूमि अभिलेख व पीएम-किसान डेटा से पात्रता का सत्यापन होगा।
5. सत्यापन के बाद राशि तीन किस्तों में डीबीटी से खाते में आएगी।
6. स्थिति SAARA पोर्टल पर देखी जा सकती है।','1. Ensure you are registered under PM-Kisan.
2. Contact your area Patwari or local Agriculture/Revenue office for application/verification.
3. Provide Aadhaar, bank passbook and land records.
4. Eligibility is verified against land records and PM-Kisan data.
5. After verification the amount is credited in three DBT installments.
6. Status can be checked on the SAARA portal.','https://saara.mp.gov.in/saaraweb/instructions.html','0755-2525804',true,false,20,'mp-kisan-kalyan','state','[{"q_hi":"मुख्यमंत्री किसान कल्याण योजना में कितने रुपये मिलते हैं?","q_en":"How much money is given under Mukhyamantri Kisan Kalyan Yojana?","a_hi":"इस योजना में मध्यप्रदेश सरकार पात्र किसानों को हर साल 6,000 रुपये देती है, जो 2,000-2,000 रुपये की तीन किस्तों में डीबीटी के माध्यम से सीधे बैंक खाते में जमा होते हैं। यह राशि पीएम-किसान सम्मान निधि के 6,000 रुपये के अतिरिक्त है, इसलिए किसान को दोनों योजनाओं से मिलाकर कुल 12,000 रुपये प्रति वर्ष प्राप्त होते हैं।","a_en":"The MP government gives eligible farmers Rs 6,000 per year in three DBT installments of Rs 2,000. This is over and above PM-Kisan''s Rs 6,000, so a farmer receives a combined total of Rs 12,000 per year."},{"q_hi":"क्या पीएम-किसान में पंजीकरण जरूरी है?","q_en":"Is PM-Kisan registration mandatory?","a_hi":"हां, यह योजना पीएम-किसान का राज्य-स्तरीय टॉप-अप है, इसलिए इसका लाभ केवल उन्हीं किसानों को मिलता है जो पहले से पीएम-किसान सम्मान निधि योजना में पंजीकृत और सत्यापित हैं। यदि आप पीएम-किसान में पंजीकृत नहीं हैं, तो पहले वहां पंजीकरण और ई-केवाईसी पूरी करें।","a_en":"Yes. This is a state-level top-up to PM-Kisan, so only farmers already registered and verified under PM-Kisan receive it. If not registered, first complete PM-Kisan registration and e-KYC."},{"q_hi":"आवेदन कहां और कैसे करें?","q_en":"Where and how do I apply?","a_hi":"अधिकांश पात्र किसानों का चयन पीएम-किसान और राजस्व अभिलेखों के आधार पर स्वतः हो जाता है। यदि लाभ नहीं मिल रहा है तो अपने क्षेत्र के पटवारी या स्थानीय कृषि/राजस्व कार्यालय से संपर्क करें और आधार, बैंक पासबुक तथा भूमि अभिलेख उपलब्ध कराएं। स्थिति SAARA पोर्टल पर देखी जा सकती है, या हेल्पलाइन 0755-2525804 पर संपर्क करें।","a_en":"Most eligible farmers are selected automatically from PM-Kisan and revenue records. If not receiving it, contact your Patwari or local Agriculture/Revenue office with Aadhaar, bank passbook and land records. Check status on the SAARA portal or call 0755-2525804."},{"q_hi":"किस्त क्यों नहीं आई, क्या करें?","q_en":"My installment did not arrive, what should I do?","a_hi":"सामान्य कारणों में आधार-बैंक लिंकिंग न होना, ई-केवाईसी अधूरी होना, भूमि अभिलेखों में विसंगति या पीएम-किसान की स्थिति लंबित होना शामिल है। पहले पीएम-किसान पोर्टल पर अपनी स्थिति व ई-केवाईसी जांचें, फिर बैंक में आधार सीडिंग की पुष्टि करें। समस्या बनी रहे तो पटवारी/कृषि कार्यालय या हेल्पलाइन 0755-2525804 पर संपर्क करें।","a_en":"Common reasons: account not Aadhaar-linked, incomplete e-KYC, land-record discrepancies, or a pending PM-Kisan status. Check your status/e-KYC on the PM-Kisan portal, confirm Aadhaar seeding at your bank, then contact the Patwari/Agriculture office or call 0755-2525804."}]'::jsonb,'आधार कार्ड, पीएम-किसान पंजीकरण संख्या/फार्मर आईडी, भूमि स्वामित्व अभिलेख (खसरा/खतौनी/बी-1), बैंक पासबुक, आधार से जुड़ा मोबाइल नंबर, फार्मर रजिस्ट्री आईडी','Aadhaar card, PM-Kisan registration number/Farmer ID, land ownership records (Khasra/Khatauni/B-1), bank passbook, Aadhaar-linked mobile number, Farmer Registry ID','https://www.govtschemes.in/mukhyamantri-kisan-kalyan-yojana','2026-09-24') on conflict (id) do nothing;
insert into public.sarkari_yojana (id,scheme_name_hi,scheme_name_en,ministry_hi,ministry_en,category,description_hi,description_en,benefit_hi,benefit_en,eligibility_hi,eligibility_en,how_to_apply_hi,how_to_apply_en,official_website,helpline,is_active,is_featured,sort_order,slug,government_level,faqs,documents_required_hi,documents_required_en,source_url,last_verified_date) values ('00000000-0000-4000-c000-000000000010','ई-कृषि यंत्र अनुदान योजना','e-Krishi Yantra Anudan Yojana (Farm Machinery Subsidy)','मध्यप्रदेश शासन, किसान कल्याण तथा कृषि विकास विभाग','Govt of Madhya Pradesh, Department of Farmer Welfare & Agriculture Development','machinery','ई-कृषि यंत्र अनुदान योजना मध्यप्रदेश सरकार का ऑनलाइन पोर्टल है जिसके जरिए किसानों को आधुनिक कृषि यंत्रों और मशीनों की खरीद पर सब्सिडी (अनुदान) दी जाती है। इसमें हैप्पी सीडर, सुपर सीडर, ज़ीरो टिल ड्रिल, बेलर, स्ट्रॉ रीपर जैसे कई यंत्र शामिल हैं। छोटे/सीमांत किसानों को लगभग 40-50% और अन्य किसानों को 30-40% तक अनुदान मिलता है। आवेदन dbt.mpdage.org पर होता है और चयन लॉटरी से होता है।','e-Krishi Yantra Anudan Yojana is the MP government online portal giving farmers subsidy on modern farm equipment (Happy Seeder, Super Seeder, Zero Till Drill, Baler, Straw Reaper, etc.). Small/marginal farmers get ~40-50% and other farmers 30-40%. Applications are on dbt.mpdage.org and beneficiaries are chosen by lottery.','किसानों को चयनित आधुनिक कृषि यंत्रों की खरीद पर सरकार से अनुदान मिलता है, जिससे खेती की लागत और समय दोनों घटते हैं। छोटे व सीमांत किसानों को लगभग 40-50% तथा अन्य किसानों को 30-40% तक सब्सिडी मिलती है। हैप्पी सीडर/सुपर सीडर जैसे यंत्र पराली प्रबंधन में भी मदद करते हैं।','Farmers get subsidy on selected modern implements, cutting cost and time. Small/marginal farmers get ~40-50%, others 30-40%. Machines like Happy/Super Seeder also help stubble management.','आवेदक मध्यप्रदेश का किसान हो और उसके नाम पर कृषि भूमि हो; कुछ यंत्रों के लिए न्यूनतम भूमि/ट्रैक्टर की शर्त हो सकती है; एससी/एसटी किसानों के लिए जाति प्रमाण-पत्र आवश्यक; आवेदन के साथ यंत्र के अनुसार 2,000 से 15,000 रुपये तक की धरोहर राशि (डीडी) जमा करनी होती है।','MP farmer with agricultural land in own name; some implements need minimum land/tractor; SC/ST need caste certificate; a security deposit (DD) of Rs 2,000-15,000 depending on equipment is required with the application.','1. dbt.mpdage.org या farmer.mpdage.org पोर्टल खोलें।
2. आधार सत्यापन कर पंजीकरण करें।
3. व्यक्तिगत, भूमि व कृषि संबंधी जानकारी भरें।
4. आवश्यक दस्तावेज व धरोहर राशि की डीडी अपलोड करें।
5. यंत्र चुनकर आवेदन जमा करें और पंजीयन नंबर सुरक्षित रखें।
6. निर्धारित तिथि पर लॉटरी से चयन होता है।','1. Open dbt.mpdage.org or farmer.mpdage.org.
2. Register after Aadhaar verification.
3. Fill personal, land and farming details.
4. Upload documents and the security-deposit DD.
5. Select the implement, submit and save the registration number.
6. Selection is by lottery on the notified date.','https://dbt.mpdage.org/',null,true,false,21,'e-krishi-yantra','state','[{"q_hi":"ई-कृषि यंत्र अनुदान में कितनी सब्सिडी मिलती है?","q_en":"How much subsidy is given?","a_hi":"अनुदान की राशि यंत्र के प्रकार और किसान की श्रेणी पर निर्भर करती है। सामान्यतः छोटे व सीमांत किसानों को यंत्र की लागत का लगभग 40-50% और अन्य किसानों को 30-40% तक अनुदान मिलता है। हर यंत्र के लिए अलग दर होती है, इसलिए सटीक राशि जानने के लिए पोर्टल पर उपलब्ध सब्सिडी कैलकुलेटर का उपयोग करें।","a_en":"It depends on the implement and farmer category — generally ~40-50% for small/marginal and 30-40% for others. Rates differ per implement; use the subsidy calculator on the portal for the exact amount."},{"q_hi":"आवेदन कहां करें?","q_en":"Where do I apply?","a_hi":"आवेदन पूरी तरह ऑनलाइन होता है। dbt.mpdage.org या farmer.mpdage.org पर जाकर आधार से पंजीकरण करें, जानकारी भरें, दस्तावेज व धरोहर राशि की डीडी अपलोड करें और यंत्र चुनकर आवेदन जमा करें। आवेदन के बाद मिला पंजीयन/सत्यापन नंबर संभालकर रखें।","a_en":"Fully online: go to dbt.mpdage.org or farmer.mpdage.org, register with Aadhaar, fill details, upload documents and the security-deposit DD, select the implement and submit. Keep the registration number."},{"q_hi":"चयन कैसे होता है?","q_en":"How are beneficiaries selected?","a_hi":"प्राप्त आवेदनों में से लाभार्थियों का चयन लॉटरी प्रणाली द्वारा किया जाता है। विभाग आवेदन की अंतिम तिथि के बाद निर्धारित दिन लॉटरी निकालता है और चयनित किसानों की सूची पोर्टल पर प्रकाशित करता है। चयन के बाद किसान को तय समय में शेष भुगतान कर यंत्र खरीदना होता है और सत्यापन के बाद अनुदान मिलता है।","a_en":"By lottery. After the deadline the department draws the lottery and publishes the selected list on the portal. Selected farmers pay the balance within the set time, buy the implement, and get the subsidy after verification."},{"q_hi":"किन यंत्रों पर अनुदान मिलता है?","q_en":"Which implements are covered?","a_hi":"योजना में हैप्पी सीडर, सुपर सीडर, स्मार्ट सीडर, ज़ीरो टिल सीड कम फर्टिलाइज़र ड्रिल, बेलर, हे रेक/स्ट्रॉ रेक, स्ट्रॉ रीपर, श्रेडर/मल्चर और स्लेशर आदि शामिल हैं। हर वर्ष उपलब्ध यंत्रों और अंतिम तिथियों की सूची पोर्टल पर अलग-अलग जारी होती है, इसलिए आवेदन से पहले पोर्टल पर वर्तमान सूची अवश्य देखें।","a_en":"Happy Seeder, Super Seeder, Smart Seeder, Zero Till drill, Baler, Hay/Straw Rake, Straw Reaper, Shredder/Mulcher, Slasher and more. The available list and deadlines are issued each year on the portal, so check the current list before applying."}]'::jsonb,'आधार कार्ड, बैंक पासबुक की पहली पृष्ठ की प्रति, धरोहर राशि की डिमांड ड्राफ्ट (डीडी), भूमि अभिलेख (खसरा/खतौनी/बी-1), जाति प्रमाण-पत्र (केवल एससी/एसटी वर्ग के लिए)','Aadhaar card, copy of bank passbook first page, Demand Draft (DD) for security deposit, land records (Khasra/Khatauni/B-1), caste certificate (SC/ST only)','https://dbt.mpdage.org/','2026-09-24') on conflict (id) do nothing;
insert into public.sarkari_yojana (id,scheme_name_hi,scheme_name_en,ministry_hi,ministry_en,category,description_hi,description_en,benefit_hi,benefit_en,eligibility_hi,eligibility_en,how_to_apply_hi,how_to_apply_en,official_website,helpline,is_active,is_featured,sort_order,slug,government_level,faqs,documents_required_hi,documents_required_en,source_url,last_verified_date) values ('00000000-0000-4000-c000-000000000011','बलराम तालाब योजना','Balram Talab Yojana (Farm Pond Scheme)','मध्यप्रदेश शासन, किसान कल्याण तथा कृषि विकास विभाग','Govt of Madhya Pradesh, Department of Farmer Welfare & Agriculture Development','irrigation','बलराम तालाब योजना मध्यप्रदेश सरकार की सिंचाई योजना है जिसमें किसानों को अपने खेत में तालाब बनवाने पर अनुदान मिलता है, ताकि भूजल और सतही जल का संरक्षण हो और सिंचाई के लिए पानी की कमी न रहे। सामान्य किसानों को लागत का 40% या अधिकतम 80,000 रुपये तथा अनुसूचित जाति/जनजाति के किसानों को 75% या अधिकतम 1 लाख रुपये तक अनुदान मिलता है। आवेदन farmer.mpdage.org पोर्टल पर होता है।','Balram Talab Yojana is an MP irrigation scheme giving farmers a subsidy to build a farm pond, conserving groundwater and ensuring irrigation water. General farmers get 40% of cost or max Rs 80,000; SC/ST farmers get 75% or up to Rs 1 lakh. Applications are on farmer.mpdage.org.','किसान अपने खेत में तालाब बनवाकर वर्षा जल संचय कर सकते हैं और सूखे के समय सिंचाई का स्थायी स्रोत पा सकते हैं। सामान्य वर्ग के किसानों को लागत का 40% या अधिकतम 80,000 रुपये और एससी/एसटी किसानों को 75% या अधिकतम 1 लाख रुपये तक अनुदान मिलता है।','Farmers harvest rainwater with a farm pond and get a permanent irrigation source. General farmers get 40% or max Rs 80,000; SC/ST get 75% or up to Rs 1 lakh.','आवेदक मध्यप्रदेश का निवासी हो और उसके नाम खेती योग्य भूमि हो (पट्टे की भूमि पात्र नहीं); किसान ने वर्ष 2017-18 या उसके बाद सरकारी योजना के तहत ड्रिप/स्प्रिंकलर सिस्टम लगाया हो और वह चालू स्थिति में हो; तालाब किसान की अपनी भूमि पर बनाया जाए; लाभ एक किसान को केवल एक बार मिलता है।','Resident of MP with cultivable land in own name (leased land not eligible); installed a drip/sprinkler system under a govt scheme in 2017-18 or later, still working; pond built on own land; benefit once per farmer.','1. farmer.mpdage.org पोर्टल खोलें।
2. आधार से पंजीकरण/लॉगिन करें।
3. बलराम तालाब योजना चुनकर व्यक्तिगत व भूमि की जानकारी भरें।
4. आवश्यक दस्तावेज अपलोड करें।
5. आवेदन जमा कर पंजीयन नंबर सुरक्षित रखें।
6. विभागीय सत्यापन के बाद तालाब निर्माण कराएं; पूरा होने पर अनुदान खाते में आता है।','1. Open farmer.mpdage.org.
2. Register/login with Aadhaar.
3. Select Balram Talab Yojana and fill personal and land details.
4. Upload the required documents.
5. Submit and keep the registration number.
6. After verification, build the pond; the subsidy is credited once complete.','https://farmer.mpdage.org/',null,true,false,22,'balram-talab','state','[{"q_hi":"बलराम तालाब योजना में कितनी सब्सिडी मिलती है?","q_en":"How much subsidy is available?","a_hi":"सामान्य वर्ग के किसानों को तालाब निर्माण की लागत का 40% या अधिकतम 80,000 रुपये तक अनुदान मिलता है। अनुसूचित जाति और अनुसूचित जनजाति के किसानों को लागत का 75% या अधिकतम 1 लाख रुपये तक। सटीक राशि तालाब के आकार और स्वीकृत अनुमानित लागत पर निर्भर करती है, इसलिए आवेदन के समय विभाग से पुष्टि कर लें।","a_en":"General category farmers get 40% or max Rs 80,000; SC/ST get 75% or up to Rs 1 lakh. The exact amount depends on pond size and approved estimated cost — confirm with the department while applying."},{"q_hi":"क्या ड्रिप या स्प्रिंकलर लगाना जरूरी है?","q_en":"Is a drip or sprinkler system necessary?","a_hi":"हां, पात्रता की एक प्रमुख शर्त यह है कि किसान ने वर्ष 2017-18 या उसके बाद किसी सरकारी योजना के तहत ड्रिप या स्प्रिंकलर सिंचाई प्रणाली लगाई हो और वह वर्तमान में चालू स्थिति में हो। इसका उद्देश्य यह है कि तालाब के पानी का उपयोग सूक्ष्म-सिंचाई के जरिए किफायती और कुशल तरीके से हो सके।","a_en":"Yes — a key condition is that the farmer installed a drip/sprinkler system under a government scheme in 2017-18 or later, currently working, so the pond water is used efficiently via micro-irrigation."},{"q_hi":"क्या पट्टे की जमीन पर तालाब बनवा सकते हैं?","q_en":"Can I build a pond on leased land?","a_hi":"नहीं। योजना का लाभ केवल उन्हीं किसानों को मिलता है जिनके नाम खेती योग्य भूमि है। पट्टे या लीज पर ली गई भूमि पर तालाब बनवाने के लिए अनुदान नहीं दिया जाता। तालाब किसान की अपनी स्वामित्व वाली भूमि पर ही बनाया जाना चाहिए, और इसके लिए भूमि अभिलेख (खसरा/खतौनी) प्रस्तुत करना आवश्यक है।","a_en":"No. Only farmers with cultivable land in their own name are eligible; leased/rented land does not qualify. The pond must be on owned land, and land records (Khasra/Khatauni) must be submitted."},{"q_hi":"क्या यह लाभ एक से अधिक बार मिल सकता है?","q_en":"Can this benefit be availed more than once?","a_hi":"नहीं, बलराम तालाब योजना का लाभ एक किसान को केवल एक बार ही मिलता है। एक बार तालाब निर्माण पर अनुदान प्राप्त करने के बाद उसी किसान को दोबारा इस योजना के तहत अनुदान नहीं दिया जाता, ताकि अधिक से अधिक किसानों को योजना का लाभ मिल सके।","a_en":"No, the benefit can be availed only once per farmer, so that as many farmers as possible can benefit."}]'::jsonb,'आधार कार्ड, पहचान प्रमाण, मूल निवास प्रमाण-पत्र, बैंक पासबुक की प्रति, पासपोर्ट आकार का फोटो, भूमि अभिलेख (खसरा/खतौनी), ड्रिप/स्प्रिंकलर स्थापना का प्रमाण','Aadhaar card, identity proof, domicile certificate, bank passbook copy, passport-size photo, land records (Khasra/Khatauni), proof of drip/sprinkler installation','https://www.krishakjagat.org/government-schemes/subsidy-for-making-pond-in-the-field-under-the-state-scheme-balaram-talab-yojana/','2026-09-24') on conflict (id) do nothing;
insert into public.sarkari_yojana (id,scheme_name_hi,scheme_name_en,ministry_hi,ministry_en,category,description_hi,description_en,benefit_hi,benefit_en,eligibility_hi,eligibility_en,how_to_apply_hi,how_to_apply_en,official_website,helpline,is_active,is_featured,sort_order,slug,government_level,faqs,documents_required_hi,documents_required_en,source_url,last_verified_date) values ('00000000-0000-4000-c000-000000000012','मुख्यमंत्री सोलर पंप योजना (कुसुम-ब)','Mukhyamantri Solar Pump Yojana (KUSUM-B)','मध्यप्रदेश शासन, नवीन एवं नवकरणीय ऊर्जा विभाग','Govt of Madhya Pradesh, Department of New & Renewable Energy','solar','मुख्यमंत्री सोलर पंप योजना (कुसुम-ब घटक) मध्यप्रदेश सरकार की योजना है जिसमें किसानों को सिंचाई के लिए सौर ऊर्जा से चलने वाले पंप भारी अनुदान पर उपलब्ध कराए जाते हैं। इससे किसान डीजल और बिजली के बिल से मुक्त होकर दिन में सिंचाई कर सकते हैं। योजना में 1 एचपी से 7.5 एचपी तक के सोलर पंप दिए जाते हैं। आवेदन के लिए पोर्टल पर पंजीयन शुल्क जमा करना होता है।','Mukhyamantri Solar Pump Yojana (KUSUM-B) provides MP farmers solar irrigation pumps at heavy subsidy, freeing them from diesel and power bills and enabling daytime irrigation. Pumps from 1 HP to 7.5 HP are offered; a registration fee is paid on the portal to apply.','किसानों को सौर ऊर्जा से चलने वाले सिंचाई पंप भारी अनुदान पर मिलते हैं, जिससे बिजली कनेक्शन या डीजल पर निर्भरता खत्म होती है और बिजली बिल की बचत होती है। 1 एचपी से 7.5 एचपी क्षमता तक के पंप उपलब्ध हैं। अनुदान केंद्र व राज्य सरकार की नीति के अनुसार तय होता है।','Solar irrigation pumps at heavy subsidy end dependence on grid power or diesel and save on bills. Pumps of 1-7.5 HP are available; subsidy is per central and state policy.','आवेदक मध्यप्रदेश का किसान हो (शहरी व ग्रामीण दोनों); जिस कृषि भूमि पर पंप लगाना है वहां पहले से बिजली का पंप कनेक्शन न हो; सिंचाई के लिए स्थायी जल स्रोत उपलब्ध हो; आवश्यक जल भंडारण/ढांचा मौजूद हो।','MP farmer (urban and rural); the target land must not already have an electric pump connection; a permanent water source and required water-storage infrastructure must exist.','1. आधिकारिक पोर्टल cmsolarpump.mp.gov.in खोलें।
2. आवश्यक जानकारी भरकर ऑनलाइन पंजीयन करें।
3. निर्धारित पंजीयन शुल्क (5,000 रुपये) जमा करें।
4. मध्यप्रदेश ऊर्जा विकास निगम द्वारा चयन/स्वीकृति की सूचना दी जाती है।
5. चयन के बाद शेष राशि NEFT/RTGS/चेक/डीडी से जमा करें।
6. इसके बाद निगम द्वारा सोलर पंप स्थापित किया जाता है।','1. Open cmsolarpump.mp.gov.in.
2. Register online with required details.
3. Pay the registration fee (Rs 5,000).
4. The MP Energy Development Corporation notifies selection/approval.
5. After selection, deposit the balance via NEFT/RTGS/cheque/DD.
6. The Corporation then installs the solar pump.','https://cmsolarpump.mp.gov.in/',null,true,false,23,'mp-solar-pump-kusum-b','state','[{"q_hi":"सोलर पंप योजना में कितना अनुदान मिलता है?","q_en":"How much subsidy is given?","a_hi":"मुख्यमंत्री सोलर पंप योजना (कुसुम-ब) में किसानों को सोलर पंप पर भारी अनुदान मिलता है। अनुदान की सटीक दर केंद्र और राज्य सरकार की उस समय की नीति के अनुसार तय होती है और पंप की क्षमता (1 एचपी से 7.5 एचपी) पर निर्भर करती है। शेष राशि किसान को स्वयं वहन करनी होती है। सटीक अंशदान जानने के लिए आवेदन के समय पोर्टल पर वर्तमान दरें अवश्य देखें।","a_en":"Farmers get a heavy subsidy on the pump. The exact rate is per central/state policy at the time and depends on pump capacity (1-7.5 HP); the farmer bears the rest. Check current rates on the portal while applying."},{"q_hi":"पंजीयन शुल्क कितना है और कैसे जमा करें?","q_en":"What is the registration fee and how do I pay it?","a_hi":"आवेदन के समय किसान को 5,000 रुपये का पंजीयन शुल्क जमा करना होता है, जो आवेदन के साथ अनिवार्य है। यह भुगतान आधिकारिक पोर्टल cmsolarpump.mp.gov.in पर ऑनलाइन किया जाता है। चयन के बाद शेष राशि NEFT/RTGS/चेक या डीडी के माध्यम से निर्धारित समय-सीमा में जमा करनी होती है।","a_en":"A registration fee of Rs 5,000 is mandatory with the application, paid online at cmsolarpump.mp.gov.in. After selection, the balance is deposited via NEFT/RTGS/cheque/DD within the specified time."},{"q_hi":"अगर खेत में पहले से बिजली कनेक्शन है तो क्या पंप मिलेगा?","q_en":"If my farm already has an electricity connection, can I still get the pump?","a_hi":"नहीं। योजना का उद्देश्य उन किसानों तक सिंचाई पहुंचाना है जिनके खेत में पहले से बिजली का पंप कनेक्शन नहीं है। यदि आपकी उसी कृषि भूमि पर पहले से विद्युत पंप कनेक्शन मौजूद है, तो आप उस भूमि के लिए इस योजना के पात्र नहीं होंगे। सिंचाई हेतु स्थायी जल स्रोत का होना भी आवश्यक है।","a_en":"No. The scheme targets farms without an existing electric pump connection. If your land already has one, it is not eligible; a permanent water source is also required."},{"q_hi":"आवेदन कहां करें?","q_en":"Where do I apply?","a_hi":"आवेदन नवीन एवं नवकरणीय ऊर्जा विभाग / मध्यप्रदेश ऊर्जा विकास निगम के आधिकारिक पोर्टल cmsolarpump.mp.gov.in पर ऑनलाइन किया जाता है। पोर्टल पर जानकारी भरकर पंजीयन करें, 5,000 रुपये शुल्क जमा करें और आवेदन प्रस्तुत करें। चयन की सूचना निगम द्वारा दी जाती है।","a_en":"Apply online at cmsolarpump.mp.gov.in (New & Renewable Energy Dept / MP Energy Development Corporation). Register, pay the Rs 5,000 fee and submit. The Corporation notifies selection."}]'::jsonb,'आधार कार्ड, भूमि अभिलेख (खसरा/खतौनी/बी-1), बैंक पासबुक की प्रति, आधार से जुड़ा मोबाइल नंबर, पासपोर्ट आकार का फोटो, पंजीयन शुल्क भुगतान का प्रमाण','Aadhaar card, land records (Khasra/Khatauni/B-1), bank passbook copy, Aadhaar-linked mobile number, passport-size photo, proof of registration-fee payment','https://cmhelpline.mp.gov.in/Schmedetail.aspx?Schemeid=927','2026-09-24') on conflict (id) do nothing;

-- F6. central-scheme FAQ/doc/source backfill (by slug)
update public.sarkari_yojana set faqs='[{"q_hi":"पीएम किसान में मुझे कितने पैसे और कब मिलते हैं?","q_en":"How much money do I get under PM Kisan and when?","a_hi":"इस योजना में हर पात्र किसान परिवार को साल में कुल ₹6,000 मिलते हैं, जो ₹2,000 की तीन बराबर किस्तों में सीधे आपके बैंक खाते में भेजे जाते हैं। यह राशि किसान परिवार (पति, पत्नी और नाबालिग बच्चे) की एक इकाई को मिलती है। किस्तों की सही तारीख और स्थिति pmkisan.gov.in पर देख सकते हैं।","a_en":"Every eligible farmer family receives ₹6,000 per year in three equal installments of ₹2,000 directly to the bank account. It is given to one farmer family unit. Check dates and status on pmkisan.gov.in."},{"q_hi":"मैं पीएम किसान के लिए पात्र हूँ या नहीं?","q_en":"Am I eligible for PM Kisan?","a_hi":"जिन छोटे और सीमांत किसानों के पास खेती योग्य ज़मीन है, वे सभी पात्र हैं। लेकिन आयकर देने वाले, सरकारी कर्मचारी और पेंशनधारी इस योजना के लिए पात्र नहीं हैं। लाभ किसान परिवार को एक इकाई के रूप में मिलता है। संदेह हो तो pmkisan.gov.in देखें या KVK सागर से संपर्क करें।","a_en":"All small and marginal farmers who own cultivable land are eligible. Income-tax payers, government employees and pensioners are not. The benefit goes to the family as one unit. If unsure, check pmkisan.gov.in or contact KVK Sagar."},{"q_hi":"पीएम किसान में पंजीकरण कैसे करें?","q_en":"How do I register for PM Kisan?","a_hi":"pmkisan.gov.in पर \"New Farmer Registration\" पर क्लिक करें, फिर आधार नंबर, मोबाइल नंबर और बैंक खाता जानकारी भरें और ज़मीन के कागज़ अपलोड करें। पंजीकरण व सत्यापन के बाद किस्त आना शुरू हो जाती है। नज़दीकी CSC केंद्र से भी पंजीकरण करवाया जा सकता है।","a_en":"On pmkisan.gov.in click \"New Farmer Registration\", enter Aadhaar, mobile and bank details, and upload land records. Installments begin after verification. You can also register at a CSC centre."},{"q_hi":"पीएम किसान के लिए कौन-कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"आधार कार्ड, बैंक खाता पासबुक (IFSC सहित), ज़मीन के कागज़ (खसरा-खतौनी), मोबाइल नंबर और एक पहचान पत्र (वोटर ID या पैन कार्ड) चाहिए। पंजीकरण के बाद e-KYC कराना ज़रूरी है, वरना किस्त रुक सकती है। e-KYC pmkisan.gov.in या CSC केंद्र पर हो जाती है।","a_en":"Aadhaar, bank passbook (with IFSC), land records (Khasra-Khatauni), mobile number and one ID proof (Voter ID/PAN). e-KYC after registration is mandatory or the installment may stop; do it on pmkisan.gov.in or at a CSC."},{"q_hi":"मेरी किस्त नहीं आई, क्या करूँ?","q_en":"My installment has not arrived, what should I do?","a_hi":"सबसे पहले जांचें कि आपकी e-KYC पूरी है और बैंक खाता आधार से जुड़ा है। स्थिति pmkisan.gov.in पर \"Beneficiary Status\" में देखें। समस्या बनी रहे तो हेल्पलाइन 155261 पर कॉल करें या KVK सागर से संपर्क करें। किसी बिचौलिये को पैसे न दें, पंजीकरण पूरी तरह मुफ्त है।","a_en":"First check e-KYC is complete and the account is Aadhaar-linked. See \"Beneficiary Status\" on pmkisan.gov.in. If it persists, call 155261 or contact KVK Sagar. Do not pay any middleman — registration is free."}]'::jsonb, documents_required_hi='आधार कार्ड, बैंक खाता पासबुक (IFSC सहित), ज़मीन के कागज़ (खसरा-खतौनी), मोबाइल नंबर, पहचान पत्र (वोटर ID या पैन कार्ड)। पंजीकरण के बाद e-KYC ज़रूरी है।', documents_required_en='Aadhaar card, bank account passbook (with IFSC), land records (Khasra-Khatauni), mobile number, ID proof (Voter ID or PAN). e-KYC is mandatory after registration.', source_url='https://pmkisan.gov.in', last_verified_date='2026-09-24' where slug='pm-kisan';
update public.sarkari_yojana set faqs='[{"q_hi":"फसल बीमा में मुझे प्रीमियम कितना देना होता है?","q_en":"How much premium do I pay?","a_hi":"किसान को बहुत कम प्रीमियम देना होता है — खरीफ फसलों के लिए बीमा राशि का सिर्फ 2% और रबी फसलों के लिए 1.5%। बाकी पूरा प्रीमियम सरकार भरती है। नुकसान होने पर पूरी बीमा राशि (क्लेम) मिलती है। सटीक प्रीमियम pmfby.gov.in के प्रीमियम कैलकुलेटर से देख सकते हैं।","a_en":"Farmers pay only 2% of the sum insured for Kharif and 1.5% for Rabi; the government pays the rest. On loss, the full claim is paid. Use the premium calculator on pmfby.gov.in for exact figures."},{"q_hi":"फसल बीमा के लिए कौन आवेदन कर सकता है?","q_en":"Who can apply?","a_hi":"सभी किसान आवेदन कर सकते हैं — ज़मीन मालिक, किरायेदार और बटाईदार भी। शर्त यह है कि आपकी फसल और क्षेत्र राज्य सरकार द्वारा अधिसूचित हो। सागर ज़िले में आपकी फसल अधिसूचित है या नहीं, यह नज़दीकी बैंक, CSC या KVK सागर से पता करें।","a_en":"All farmers — owners, tenants and sharecroppers. The crop and area must be notified by the state. Check with your bank, CSC or KVK Sagar whether your crop is notified in Sagar."},{"q_hi":"खरीफ फसल के बीमा की आखिरी तारीख क्या है?","q_en":"What is the last date to insure a Kharif crop?","a_hi":"खरीफ फसलों के लिए आमतौर पर 31 जुलाई से पहले आवेदन करना होता है। आवेदन pmfby.gov.in या नज़दीकी बैंक/CSC पर किया जा सकता है। आधार, बैंक खाता और खसरा नंबर साथ रखें। तारीखें साल के अनुसार बदल सकती हैं, इसलिए ताज़ा जानकारी pmfby.gov.in पर देखें।","a_en":"Usually before 31 July for Kharif. Apply on pmfby.gov.in or at a bank/CSC with Aadhaar, bank account and Khasra number. Dates change yearly — check pmfby.gov.in."},{"q_hi":"फसल खराब हो जाए तो नुकसान की सूचना कैसे दूँ?","q_en":"How do I report crop damage?","a_hi":"फसल में नुकसान होने पर 72 घंटे के अंदर सूचना देना बहुत ज़रूरी है। आप हेल्पलाइन 14447 पर कॉल करके, या फसल बीमा ऐप या pmfby.gov.in के ज़रिए सूचना दे सकते हैं। जल्दी सूचना देने से क्लेम आसानी से पास होता है। देर होने पर क्लेम रुक सकता है।","a_en":"Report within 72 hours — call 14447, or use the crop insurance app or pmfby.gov.in. Prompt reporting helps the claim pass; delay can hold it up."},{"q_hi":"फसल बीमा के लिए कौन से कागज़ चाहिए?","q_en":"What documents are required?","a_hi":"आधार कार्ड, बैंक खाता पासबुक और ज़मीन के कागज़ (खसरा नंबर/खतौनी) चाहिए। गैर-ऋणी किसानों को बुवाई प्रमाण या स्व-घोषणा, और किरायेदार/बटाईदार को किरायानामा देना पड़ सकता है। पासपोर्ट साइज़ फोटो और मोबाइल नंबर भी रखें। ऋणी किसानों का बीमा बैंक स्वतः कर देता है।","a_en":"Aadhaar, bank passbook and land records (Khasra/Khatauni). Non-loanee farmers may need a sowing certificate/self-declaration; tenants a tenancy agreement. Keep a photo and mobile number. Loanee farmers are enrolled by the bank automatically."}]'::jsonb, documents_required_hi='आधार कार्ड, बैंक खाता पासबुक, ज़मीन के कागज़ (खसरा नंबर/खतौनी), बुवाई प्रमाण/स्व-घोषणा (गैर-ऋणी किसानों के लिए), किरायेदार/बटाईदार के लिए किरायानामा, मोबाइल नंबर, पासपोर्ट साइज़ फोटो।', documents_required_en='Aadhaar card, bank passbook, land records (Khasra/Khatauni), sowing certificate/self-declaration (non-loanee), tenancy agreement for tenants, mobile number, passport-size photo.', source_url='https://pmfby.gov.in', last_verified_date='2026-09-24' where slug='pmfby';
update public.sarkari_yojana set faqs='[{"q_hi":"सोलर पंप लगाने में मुझे कितना पैसा देना होगा?","q_en":"How much will I pay to install a solar pump?","a_hi":"पीएम कुसुम योजना में सोलर पंप की कीमत पर 60% सब्सिडी सरकार देती है और 30% तक बैंक लोन मिल सकता है, यानी किसान को अपनी जेब से सिर्फ लगभग 10% देना होता है। इससे डीज़ल का खर्च बचता है। सटीक लागत पंप की क्षमता (HP) पर निर्भर करती है — विवरण के लिए pmkusum.mnre.gov.in देखें।","a_en":"Under PM KUSUM the government gives 60% subsidy and up to 30% can be a bank loan, so the farmer pays only about 10%. It saves diesel cost. Exact cost depends on pump capacity — see pmkusum.mnre.gov.in."},{"q_hi":"क्या मैं सोलर पंप से बनी बिजली बेच सकता हूँ?","q_en":"Can I sell the electricity generated?","a_hi":"हाँ, योजना के तहत किसान अपनी अतिरिक्त बिजली बेचकर अतिरिक्त कमाई कर सकते हैं। ग्रिड से जुड़े सोलर सिस्टम में बची बिजली बिजली कंपनी को दी जा सकती है। यह सुविधा आपके क्षेत्र और योजना के घटक पर निर्भर करती है, इसलिए राज्य विभाग या pmkusum.mnre.gov.in से सही जानकारी लें।","a_en":"Yes — farmers can earn extra by selling surplus power. In grid-connected systems, leftover power can go to the electricity company. This depends on your area and scheme component; check your state department or pmkusum.mnre.gov.in."},{"q_hi":"पीएम कुसुम के लिए कौन आवेदन कर सकता है?","q_en":"Who can apply?","a_hi":"सभी किसान, किसान समूह, पंचायत और सहकारी समितियां आवेदन कर सकती हैं। शर्त यह है कि आपके पास खेती योग्य ज़मीन हो। आवेदन के लिए pmkusum.mnre.gov.in पर Farmer Registration करें और ज़मीन, आधार व बैंक जानकारी भरें। पंजीकरण के बाद राज्य विभाग संपर्क करेगा।","a_en":"Individual farmers, groups, panchayats and cooperatives with agricultural land. Do Farmer Registration on pmkusum.mnre.gov.in with land, Aadhaar and bank details; the state department will contact you."},{"q_hi":"सोलर पंप के लिए आवेदन कैसे करें?","q_en":"How do I apply?","a_hi":"pmkusum.mnre.gov.in पर Farmer Registration पर क्लिक करें, ज़मीन का विवरण, आधार नंबर और बैंक खाता जानकारी भरें। आवेदन जमा करने के बाद राज्य का कृषि/ऊर्जा विभाग संपर्क कर आगे की प्रक्रिया बताएगा। संदेह हो तो हेल्पलाइन 1800-180-3333 पर कॉल करें।","a_en":"Click Farmer Registration on pmkusum.mnre.gov.in, fill land, Aadhaar and bank details. After submitting, the state agriculture/energy department contacts you with next steps. If in doubt, call 1800-180-3333."},{"q_hi":"सोलर पंप के लिए कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"आमतौर पर आधार कार्ड, ज़मीन के कागज़ (खसरा-खतौनी या भूमि स्वामित्व प्रमाण), बैंक खाता पासबुक, मोबाइल नंबर और पासपोर्ट साइज़ फोटो चाहिए। बिजली कनेक्शन हो तो उसका विवरण भी लग सकता है। सटीक सूची राज्य के अनुसार बदल सकती है, इसलिए pmkusum.mnre.gov.in से पुष्टि कर लें।","a_en":"Usually Aadhaar, land records (Khasra-Khatauni or ownership proof), bank passbook, mobile number and a photo. Electricity connection details if any. The list can vary by state — confirm on pmkusum.mnre.gov.in."}]'::jsonb, documents_required_hi='आधार कार्ड, ज़मीन के कागज़ (खसरा-खतौनी/भूमि स्वामित्व प्रमाण), बैंक खाता पासबुक, मोबाइल नंबर, पासपोर्ट साइज़ फोटो, बिजली कनेक्शन विवरण (यदि लागू हो)।', documents_required_en='Aadhaar card, land records (Khasra-Khatauni/ownership proof), bank passbook, mobile number, passport-size photo, electricity connection details (if applicable).', source_url='https://pmkusum.mnre.gov.in', last_verified_date='2026-09-24' where slug='pm-kusum';
update public.sarkari_yojana set faqs='[{"q_hi":"किसान क्रेडिट कार्ड पर मुझे कितना लोन और कितने ब्याज पर मिलता है?","q_en":"How much loan and at what interest on a KCC?","a_hi":"KCC पर आप ₹3 लाख तक का लोन सिर्फ 4% ब्याज दर पर ले सकते हैं। समय पर कर्ज चुकाने पर यह और सस्ता पड़ सकता है, क्योंकि सरकार ब्याज में छूट देती है। यह लोन खेती के खर्च, बीज, खाद आदि के लिए काम आता है। सटीक शर्तों के लिए अपने बैंक से बात करें।","a_en":"Up to ₹3 lakh at just 4% interest; timely repayment can make it cheaper via a government concession. It covers farming costs, seeds, fertilizer. Ask your bank for exact terms."},{"q_hi":"किसान क्रेडिट कार्ड के लिए कौन पात्र है?","q_en":"Who is eligible?","a_hi":"सभी किसान पात्र हैं — ज़मीन मालिक, बटाईदार और किरायेदार। इसके अलावा पशुपालन करने वाले और मछुआरे भी KCC ले सकते हैं। यानी खेती के साथ पशु या मछली पालने वालों को भी सस्ता कर्ज मिल सकता है। पात्रता के लिए नज़दीकी बैंक शाखा से संपर्क करें।","a_en":"All farmers — owners, sharecroppers, tenants — plus those in animal husbandry and fishery. Contact your nearest bank branch for eligibility."},{"q_hi":"किसान क्रेडिट कार्ड के लिए आवेदन कैसे करें?","q_en":"How do I apply?","a_hi":"नज़दीकी बैंक (जैसे SBI, PNB या को-ऑपरेटिव बैंक) में KCC आवेदन फॉर्म भरें। साथ में आधार, ज़मीन के कागज़ और पासपोर्ट साइज़ फोटो ले जाएं। पीएम किसान में पहले से शामिल किसानों के लिए फॉर्म बहुत आसान है। आमतौर पर 2 सप्ताह में कार्ड मिल जाता है।","a_en":"Fill the KCC form at your nearest bank (SBI, PNB or a cooperative). Carry Aadhaar, land documents and a photo. It is simpler for existing PM Kisan farmers. The card is usually issued within 2 weeks."},{"q_hi":"किसान क्रेडिट कार्ड के लिए कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"भरा हुआ KCC फॉर्म, आधार कार्ड, ज़मीन के कागज़ (खसरा-खतौनी), 2 पासपोर्ट साइज़ फोटो और बोई गई फसल का विवरण चाहिए। पशुपालक/मछुआरे को अपने काम से जुड़ा विवरण देना होता है। पीएम किसान लाभार्थियों के लिए ज़मीन के कागज़ और फसल का ब्योरा काफी होता है।","a_en":"Filled KCC form, Aadhaar, land records (Khasra-Khatauni), 2 photos and crops-sown details. Animal husbandry/fishery applicants give activity details. For PM Kisan beneficiaries, land record and crop details usually suffice."},{"q_hi":"क्या किसान क्रेडिट कार्ड बनवाने में कोई फीस लगती है?","q_en":"Is there any fee for a KCC?","a_hi":"KCC बनवाने के लिए किसी बिचौलिये को पैसे न दें। कुछ बैंक प्रोसेसिंग या दस्तावेज़ शुल्क ले सकते हैं, जो हर बैंक में अलग होता है — यह सीधे बैंक शाखा से पूछें। कोई बड़ी रकम मांगे तो सावधान रहें और हेल्पलाइन 1800-180-1111 पर संपर्क करें।","a_en":"Do not pay any middleman. Some banks may charge a processing/documentation fee that varies — ask the branch. If someone demands a large sum, be careful and call 1800-180-1111."}]'::jsonb, documents_required_hi='भरा हुआ KCC आवेदन फॉर्म, आधार कार्ड, ज़मीन के कागज़ (खसरा-खतौनी/भूमि स्वामित्व प्रमाण), बैंक खाता विवरण, 2 पासपोर्ट साइज़ फोटो, बोई गई फसल का विवरण। पशुपालक/मछुआरों के लिए संबंधित विवरण।', documents_required_en='Filled KCC form, Aadhaar card, land records (Khasra-Khatauni/ownership proof), bank details, 2 passport-size photos, crops-sown details. Relevant details for animal husbandry/fishery.', source_url='https://www.pmkisan.gov.in/KCC.aspx', last_verified_date='2026-09-24' where slug='kcc';
update public.sarkari_yojana set faqs='[{"q_hi":"ड्रोन दीदी योजना में कितनी सब्सिडी और कमाई मिलती है?","q_en":"How much subsidy and income does it give?","a_hi":"इस योजना में महिला स्वयं सहायता समूह को ड्रोन की कीमत पर 80% सब्सिडी और मुफ्त ट्रेनिंग मिलती है। ड्रोन से किसानों के खेतों में दवा/खाद का छिड़काव करके समूह लगभग ₹1,000 से ₹1,500 प्रति एकड़ कमा सकता है। इससे महिलाओं को नियमित आमदनी मिलती है। विवरण के लिए नज़दीकी आजीविका मिशन कार्यालय से संपर्क करें।","a_en":"Women SHGs get 80% subsidy on the drone plus free training. Spraying farmers'' fields can earn about ₹1,000-1,500 per acre, giving women regular income. Contact your nearest Aajeevika Mission office for details."},{"q_hi":"ड्रोन दीदी योजना के लिए कौन पात्र है?","q_en":"Who is eligible?","a_hi":"यह योजना NRLM के तहत पंजीकृत महिला स्वयं सहायता समूहों (SHG) के लिए है। ड्रोन चलाने वाली सदस्य कम से कम 8वीं पास और 18 से 45 वर्ष की होनी चाहिए। आवेदन समूह के नाम पर होता है, किसी एक व्यक्ति के नाम पर नहीं। पात्रता के लिए आजीविका मिशन कार्यालय या KVK सागर से संपर्क करें।","a_en":"For women SHGs registered under NRLM. The drone-operating member must be at least class 8 pass and aged 18-45. The application is in the group''s name. Contact your Aajeevika Mission office or KVK Sagar."},{"q_hi":"ड्रोन दीदी योजना के लिए आवेदन कैसे करें?","q_en":"How do I apply?","a_hi":"सबसे पहले नज़दीकी आजीविका मिशन कार्यालय से संपर्क करें और अपने SHG के नाम पर आवेदन करें। फिर योजना के तहत मिलने वाली ट्रेनिंग पूरी करें और ड्रोन उड़ाने का लाइसेंस लें। इसके बाद आप अपनी छिड़काव सेवा किसान सहयोग पर लिस्ट कर सकते हैं ताकि आसपास के किसान संपर्क कर सकें।","a_en":"Contact your nearest Aajeevika Mission office and apply in your SHG''s name. Complete the training and get a drone license. Then list your spraying service on Kisan Sahyog so nearby farmers can reach you."},{"q_hi":"ड्रोन दीदी योजना के लिए कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"SHG के पंजीकरण के कागज़ (NRLM के तहत), सदस्य का आधार कार्ड, कम से कम 8वीं पास का प्रमाणपत्र, आयु प्रमाण (18-45 वर्ष), बैंक खाता विवरण, मोबाइल नंबर और पासपोर्ट साइज़ फोटो चाहिए। सटीक सूची राज्य के अनुसार बदल सकती है, इसलिए आजीविका मिशन कार्यालय से पुष्टि कर लें।","a_en":"SHG registration (NRLM), member''s Aadhaar, class-8 certificate, age proof (18-45), bank details, mobile number and a photo. The list can vary by state — confirm with the Aajeevika Mission office."},{"q_hi":"क्या ट्रेनिंग और लाइसेंस के लिए अलग से पैसे देने होंगे?","q_en":"Do I pay separately for training and license?","a_hi":"योजना के तहत महिला SHG सदस्यों को मुफ्त ट्रेनिंग दी जाती है, इसलिए बड़ी फीस नहीं देनी चाहिए। किसी बिचौलिये को पैसे न दें। ट्रेनिंग, लाइसेंस और सब्सिडी की सही प्रक्रिया के लिए केवल आधिकारिक आजीविका मिशन कार्यालय या हेल्पलाइन 1800-180-1551 से जानकारी लें।","a_en":"Training is free for women SHG members, so avoid large fees and any middleman. For the correct process on training, license and subsidy, get information only from the official Aajeevika Mission office or 1800-180-1551."}]'::jsonb, documents_required_hi='SHG पंजीकरण दस्तावेज़ (NRLM के तहत), सदस्य का आधार कार्ड, कम से कम 8वीं पास का शैक्षणिक प्रमाण, आयु प्रमाण (18-45 वर्ष), बैंक खाता विवरण, मोबाइल नंबर, पासपोर्ट साइज़ फोटो।', documents_required_en='SHG registration documents (under NRLM), member''s Aadhaar, education proof of at least class 8, age proof (18-45), bank details, mobile number, passport-size photo.', source_url='https://www.pib.gov.in/PressReleasePage.aspx?PRID=2070029', last_verified_date='2026-09-24' where slug='drone-didi';
update public.sarkari_yojana set faqs='[{"q_hi":"मृदा स्वास्थ्य कार्ड से मुझे क्या फायदा होगा?","q_en":"How does a Soil Health Card benefit me?","a_hi":"इस योजना में आपकी मिट्टी की मुफ्त जांच होती है और आपको Soil Health Card मिलता है, जिस पर लिखा होता है कि आपके खेत में कौन सा पोषक तत्व कम है और कितनी खाद डालनी चाहिए। इससे आप ज़रूरत से ज़्यादा खाद डालने से बचते हैं, पैसे बचते हैं और पैदावार बेहतर होती है। कार्ड ऑनलाइन भी मिल जाता है।","a_en":"Your soil is tested free and you get a Soil Health Card showing which nutrients are lacking and how much fertilizer to apply. This avoids over-fertilizing, saves money and improves yield. The card is also available online."},{"q_hi":"मिट्टी की जांच कितनी बार करवा सकते हैं और क्या यह मुफ्त है?","q_en":"How often can I test soil and is it free?","a_hi":"सभी किसान इस योजना का लाभ ले सकते हैं और हर 2 साल में एक बार अपनी मिट्टी की जांच करवा सकते हैं। सरकार यह प्रक्रिया मुफ्त कराती है, इसलिए किसान पर कोई खर्च नहीं आता। किसी बिचौलिये को पैसे न दें। नज़दीकी प्रयोगशाला की जानकारी किसान सहयोग → उपयोगी संपर्क में देखें।","a_en":"All farmers can test once every 2 years, free of cost. Do not pay any middleman. Find your nearest lab under Kisan Sahyog → Useful Contacts."},{"q_hi":"मिट्टी का नमूना कैसे लें और जांच के लिए कहाँ दें?","q_en":"How do I take a sample and where do I submit it?","a_hi":"खेत के अलग-अलग हिस्सों से मिट्टी लेकर मिलाएं और करीब 500 ग्राम नमूना बनाएं। इसे नज़दीकी मृदा परीक्षण प्रयोगशाला में जमा करें। जांच के बाद आमतौर पर 2 से 4 सप्ताह में Soil Health Card मिल जाता है, जिस पर खाद की सलाह लिखी होती है।","a_en":"Collect soil from different parts of the field, mix and make a ~500 g sample. Submit at your nearest soil testing lab. You usually get the Soil Health Card in 2-4 weeks with fertilizer advice."},{"q_hi":"कार्ड मिलने के बाद उसका उपयोग कैसे करें?","q_en":"How do I use the card?","a_hi":"Soil Health Card पर लिखा होता है कि आपकी मिट्टी में कौन-कौन से पोषक तत्व कितने हैं और कौन सी खाद कितनी मात्रा में डालनी चाहिए। इसी सलाह के अनुसार खाद डालें, अंदाज़े से नहीं। इससे खाद का खर्च घटता है और फसल अच्छी होती है। समझने में दिक्कत हो तो KVK सागर से मदद लें।","a_en":"The card shows nutrient levels and how much fertilizer to apply. Follow it instead of guessing — this cuts cost and improves the crop. If it is hard to understand, get help from KVK Sagar."},{"q_hi":"मृदा स्वास्थ्य कार्ड के लिए कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"आमतौर पर आधार कार्ड, ज़मीन के कागज़ (खसरा-खतौनी), मोबाइल नंबर और पीएम किसान ID (यदि हो) चाहिए। साथ में खेत के अलग-अलग हिस्सों से लिया गया करीब 500 ग्राम मिट्टी का नमूना ले जाना होता है। सटीक ज़रूरतें प्रयोगशाला के अनुसार बदल सकती हैं।","a_en":"Usually Aadhaar, land records (Khasra-Khatauni), mobile number and PM Kisan ID (if any), plus a ~500 g soil sample. Exact needs can vary by lab."}]'::jsonb, documents_required_hi='आधार कार्ड, ज़मीन के कागज़ (खसरा-खतौनी), मोबाइल नंबर, पीएम किसान ID (यदि हो)। जांच के लिए खेत के अलग-अलग हिस्सों से ली गई करीब 500 ग्राम मिट्टी।', documents_required_en='Aadhaar card, land records (Khasra-Khatauni), mobile number, PM Kisan ID (if any). For testing, about 500 g of soil from different parts of the field.', source_url='https://soilhealth.dac.gov.in', last_verified_date='2026-09-24' where slug='soil-health-card';
update public.sarkari_yojana set faqs='[{"q_hi":"e-NAM से मुझे क्या फायदा होगा?","q_en":"How does e-NAM benefit me?","a_hi":"e-NAM एक ऑनलाइन कृषि बाज़ार है जहाँ आपकी उपज की ऑनलाइन नीलामी होती है। कई खरीदार बोली लगाते हैं और आपको बेहतर दाम मिल सकता है। भुगतान सीधे आपके बैंक खाते में आता है, जिससे बिचौलियों की गुंजाइश कम होती है। इसके लिए e-NAM से जुड़ी मंडी में रजिस्टर होना ज़रूरी है।","a_en":"e-NAM is an online market where your produce is auctioned; many buyers bid so you may get a better price, paid directly to your bank account with fewer middlemen. You must register with an e-NAM connected mandi."},{"q_hi":"e-NAM पर बेचने के लिए कौन पात्र है?","q_en":"Who is eligible to sell?","a_hi":"वे सभी किसान e-NAM पर बेच सकते हैं जो e-NAM से जुड़ी मंडी में रजिस्टर्ड हैं। सबसे पहले जानें कि आपके पास की कौन सी मंडी e-NAM से जुड़ी है। सागर ज़िले में नज़दीकी e-NAM मंडी की जानकारी के लिए enam.gov.in देखें या मंडी कार्यालय से संपर्क करें।","a_en":"Any farmer registered with an e-NAM connected mandi. First find which nearby mandi is on e-NAM — check enam.gov.in or the mandi office in Sagar."},{"q_hi":"e-NAM पर रजिस्ट्रेशन कैसे करें?","q_en":"How do I register?","a_hi":"enam.gov.in पर Farmer Registration करें और जानकारी भरें। फिर अपनी उपज लेकर नज़दीकी e-NAM मंडी में जाकर ऑनलाइन नीलामी में भाग लें। रजिस्ट्रेशन नज़दीकी e-NAM मंडी में जाकर भी करवाया जा सकता है और इसके लिए कोई फीस नहीं लगती।","a_en":"Do Farmer Registration on enam.gov.in, then bring your produce to the nearest e-NAM mandi and join the online auction. You can also register at the mandi; there is no fee."},{"q_hi":"e-NAM रजिस्ट्रेशन के लिए कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"आमतौर पर आधार कार्ड, बैंक खाता पासबुक या रद्द चेक, एक पहचान पत्र (वोटर ID/पैन) और ज़मीन के कागज़ (खसरा-खतौनी) या किसान ID चाहिए। मोबाइल नंबर और पासपोर्ट साइज़ फोटो भी रखें। सटीक ज़रूरतें मंडी के अनुसार बदल सकती हैं।","a_en":"Usually Aadhaar, bank passbook or cancelled cheque, one ID (Voter ID/PAN) and land records or Farmer ID, plus mobile number and photo. Needs can vary by mandi."},{"q_hi":"e-NAM पर बेचने के बाद पैसा कब और कैसे मिलता है?","q_en":"When and how am I paid?","a_hi":"e-NAM पर उपज बिकने के बाद भुगतान सीधे आपके बैंक खाते में आता है, इसलिए बैंक खाता सही और चालू होना ज़रूरी है। पैसा मिलने का समय मंडी और भुगतान प्रक्रिया पर निर्भर करता है। देरी या समस्या हो तो हेल्पलाइन 1800-270-0224 पर संपर्क करें।","a_en":"Payment comes directly to your bank account, so it must be correct and active. Timing depends on the mandi and process. For delays, call 1800-270-0224 or contact the mandi office."}]'::jsonb, documents_required_hi='आधार कार्ड, बैंक खाता पासबुक या रद्द चेक, पहचान पत्र (वोटर ID या पैन कार्ड), ज़मीन के कागज़ (खसरा-खतौनी) या किसान ID, मोबाइल नंबर, पासपोर्ट साइज़ फोटो।', documents_required_en='Aadhaar card, bank passbook or cancelled cheque, ID proof (Voter ID/PAN), land records (Khasra-Khatauni) or Farmer ID, mobile number, passport-size photo.', source_url='https://enam.gov.in', last_verified_date='2026-09-24' where slug='e-nam';
update public.sarkari_yojana set faqs='[{"q_hi":"पीएम आशा योजना से मुझे क्या फायदा मिलता है?","q_en":"What benefit do I get from PM-AASHA?","a_hi":"इस योजना का मकसद यह है कि जब मंडी में फसल का दाम न्यूनतम समर्थन मूल्य (MSP) से कम हो जाए तो किसान को नुकसान न हो। MSP और मंडी भाव के बीच का अंतर सीधे आपके बैंक खाते में दिया जाता है। यह मुख्य रूप से दलहन, तिलहन और खोपरा जैसी अधिसूचित फसलों पर लागू होता है।","a_en":"It protects farmers when the market price falls below MSP — the difference between MSP and mandi price is paid directly to your bank account. It applies mainly to notified crops like pulses, oilseeds and copra."},{"q_hi":"पीएम आशा योजना के लिए कौन पात्र है?","q_en":"Who is eligible?","a_hi":"वे किसान पात्र हैं जिनकी फसल और क्षेत्र राज्य सरकार द्वारा अधिसूचित हैं। इसके लिए e-NAM या सरकारी खरीद केंद्र पर रजिस्टर्ड होना ज़रूरी है। सागर ज़िले में आपकी फसल इस योजना में आती है या नहीं, यह नज़दीकी कृषि विभाग कार्यालय या KVK सागर से पता करें।","a_en":"Farmers whose crop and area are notified by the state, registered at e-NAM or a procurement centre. Check with your Agriculture Department office or KVK Sagar whether your crop is covered in Sagar."},{"q_hi":"पीएम आशा योजना में पंजीकरण और आवेदन कैसे करें?","q_en":"How do I register and apply?","a_hi":"सबसे पहले नज़दीकी कृषि विभाग कार्यालय से संपर्क करें और PM-AASHA के तहत पंजीकरण कराएं। जब आपको फसल का दाम MSP से कम मिले, तब योजना के तहत आवेदन कर सकते हैं ताकि अंतर की राशि खाते में आ सके। सही प्रक्रिया के लिए कृषि विभाग या हेल्पलाइन 1800-180-1551 से जानकारी लें।","a_en":"Contact your Agriculture Department office and register under PM-AASHA. When you get a price below MSP, apply so the difference is credited. For the process, consult the department or 1800-180-1551."},{"q_hi":"पीएम आशा योजना के लिए कौन से कागज़ चाहिए?","q_en":"What documents are needed?","a_hi":"आमतौर पर आधार कार्ड, बैंक खाता पासबुक, ज़मीन के कागज़ (खसरा-खतौनी), बोई गई फसल का विवरण और मोबाइल नंबर चाहिए, साथ ही e-NAM या सरकारी खरीद केंद्र पर पंजीकरण। किरायेदार/बटाईदार को संबंधित दस्तावेज़ देने पड़ सकते हैं।","a_en":"Usually Aadhaar, bank passbook, land records (Khasra-Khatauni), crop-sown details and mobile number, plus registration at e-NAM or a procurement centre. Tenants may need extra documents."},{"q_hi":"MSP और मंडी भाव के अंतर की राशि कैसे और कब मिलती है?","q_en":"How and when do I get the MSP-price difference?","a_hi":"जब अधिसूचित फसल का मंडी भाव MSP से नीचे चला जाता है, तो अंतर की राशि सीधे आपके बैंक खाते में भेजी जाती है। इसके लिए बैंक खाता और पंजीकरण सही होना ज़रूरी है। भुगतान की प्रक्रिया और समय राज्य की व्यवस्था पर निर्भर करता है, इसलिए ताज़ा जानकारी कृषि विभाग या KVK सागर से लें।","a_en":"When a notified crop''s price falls below MSP, the difference is sent to your bank account; your account and registration must be correct. Timing depends on the state''s arrangements — check with the Agriculture Department or KVK Sagar."}]'::jsonb, documents_required_hi='आधार कार्ड, बैंक खाता पासबुक, ज़मीन के कागज़ (खसरा-खतौनी), बोई गई फसल का विवरण, मोबाइल नंबर, e-NAM या सरकारी खरीद केंद्र पर पंजीकरण। किरायेदार/बटाईदार के लिए संबंधित दस्तावेज़।', documents_required_en='Aadhaar card, bank passbook, land records (Khasra-Khatauni), crop-sown details, mobile number, registration at e-NAM or a procurement centre. Relevant documents for tenants.', source_url='https://www.pib.gov.in/PressReleasePage.aspx?PRID=2085530', last_verified_date='2026-09-24' where slug='pm-aasha';
